cases.text:
rule 1st_rule
{
    condition:
        filesize < 1KB
}

rule condition
{
    condition:
        filesize < 1KB
}

rule BadHex
{
    strings:
        $h = { 4D 5A G0 [6-2] }
    condition:
        filesize < 1MB and $h
}

rule NoImport
{
    condition:
        filesize < 1MB and pe.is_dll()
}

rule NoCondition
{
    strings:
        $a = "abcdef"
}

rule ShortString
{
    strings:
        $a = "ab"
        $h = { 4D 5A }
    condition:
        filesize < 1MB and any of them
}

/* header comment with "quotes" and { braces } */
rule Commented // trailing comment
{
    strings:
        $a = "abc//def" // not a comment inside the string
    condition:
        filesize < 1MB and $a
}
